select count(*) as aggregate from `stores` where exists (select * from `modules` where `stores`.`module_id` = `modules`.`id` and `status` = 1) and `status` = 1 and (`store_business_model` = 'commission' or exists (select * from `store_subscriptions` inner join (select MAX(`store_subscriptions`.`id`) as `id_aggregate`, `store_subscriptions`.`store_id` from `store_subscriptions` group by `store_subscriptions`.`store_id`) as `latestOfMany` on `latestOfMany`.`id_aggregate` = `store_subscriptions`.`id` and `latestOfMany`.`store_id` = `store_subscriptions`.`store_id` where `stores`.`id` = `store_subscriptions`.`store_id` and (`max_order` = 'unlimited' or `max_order` > 0) and `status` = 1)) and `stores`.`active` = 1 and `zone_id` in (2) and NOT (stores.delivery_mode = 'walking' AND COALESCE(CASE WHEN stores.latitude REGEXP '^-?[0-9]+([.][0-9]+)?$' AND stores.longitude REGEXP '^-?[0-9]+([.][0-9]+)?$' AND CAST(stores.latitude AS DECIMAL(10,7)) BETWEEN -90 AND 90 AND CAST(stores.longitude AS DECIMAL(11,7)) BETWEEN -180 AND 180 THEN ST_Distance_Sphere(point(stores.longitude, stores.latitude), point(54.37734379999999845E0, 24.45388399999999862E0)) END > 1000.00000000000000000E0, 0));
